import hashlib
import math

class BloomFilter:
    """
    A Bloom filter implementation to test membership over a set.
    This class uses a calculated optimal size for the bit array and number of hash functions based on expected items and desired false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        # Calculate optimal size of the bit array
        self.size = self._optimal_bit_array_size(expected_items, false_positive_rate)
        # Calculate optimal number of hash functions
        self.num_hashes = self._optimal_number_of_hashes(expected_items, self.size)
        # Initialize the bit array
        self.bit_array = [0] * self.size

    @staticmethod
    def _optimal_bit_array_size(expected_items: int, false_positive_rate: float) -> int:
        """Calculate the optimum size of the bit array."""
        return math.ceil(-(expected_items * math.log(false_positive_rate)) / (math.log(2) ** 2))

    @staticmethod
    def _optimal_number_of_hashes(expected_items: int, bit_array_size: int) -> int:
        """Calculate the optimal number of hash functions to use."""
        return math.ceil((bit_array_size / expected_items) * math.log(2))

    def _hashes(self, item: str) -> list:
        """Generate a list of hash values for the given item."""
        return [int(hashlib.md5(item.encode()).hexdigest(), 16) % self.size for _ in range(self.num_hashes)]

    def add(self, item: str) -> None:
        """Add an item to the Bloom filter."""
        for hash_value in self._hashes(item):
            self.bit_array[hash_value] = 1

    def contains(self, item: str) -> bool:
        """Check if the item is in the Bloom filter."""
        return all(self.bit_array[hash_value] for hash_value in self._hashes(item))

